/** Mapea el tipo de evento de notificación a la plantilla WhatsApp correspondiente. */
export function templateForEventType(eventType: string): WhatsAppTemplateName | null {
  switch (eventType) {
    case 'task_assigned':
      return 'task_assigned_approval_es';
    case 'task_modified':
      return 'task_modified_es';
    case 'task_cancelled':
      return 'task_cancelled_es';
    case 'task_approval_reminder':
      return 'task_approval_reminder_es';
    case 'task_late_start_reminder':
      return 'task_late_start_reminder_es';
    case 'task_rejected_alert':
      return 'task_rejected_admin_alert_es';
    default:
      return null;
  }
}

/** Construye los componentes "body" de la API de Meta a partir de parámetros de texto. */
export function buildBodyComponent(bodyParameters: string[]) {
  return {
    type: 'body',
    parameters: bodyParameters.map((text) => ({ type: 'text', text })),
  };
}

// Semántica pura del efecto externo Meta. Separada del cliente HTTP para que
// pueda probarse sin red, credenciales ni runtime Deno.
export function isAmbiguousWhatsAppHttpStatus(status: number): boolean {
  return status >= 500 || [408, 429].includes(status);
}

export const TERMINAL_APPROVAL_CALLBACK_OUTCOMES = new Set([
  'invalid',
  'expired',
  'stale',
  'superseded',
  'not_actionable',
  'unauthorized_sender',
  'duplicate',
  'applied',
]);

const REJECTION_OUTCOMES_REQUIRING_DERIVED_EVENT = new Set(['applied', 'duplicate']);

export interface ApprovalCallbackClassification {
  processed: boolean;
  derivedEventId: string | null;
  missingDerivedEvent: boolean;
}

/**
 * Clasifica el resultado durable de un botón sin confundir un rechazo
 * descartado con una decisión aplicada. Solo applied/duplicate de una acción
 * reject necesitan enviar (o reutilizar) la alerta derivada.
 */
export function classifyApprovalCallbackOutcome(
  action: string | null | undefined,
  outcome: string | null | undefined,
  rejectionEventId: string | null | undefined,
): ApprovalCallbackClassification {
  if (!outcome || !TERMINAL_APPROVAL_CALLBACK_OUTCOMES.has(outcome)) {
    return { processed: false, derivedEventId: null, missingDerivedEvent: false };
  }

  const requiresDerivedEvent = action === 'reject'
    && REJECTION_OUTCOMES_REQUIRING_DERIVED_EVENT.has(outcome);
  if (!requiresDerivedEvent) {
    return { processed: true, derivedEventId: null, missingDerivedEvent: false };
  }

  const derivedEventId = rejectionEventId?.trim() || null;
  return derivedEventId
    ? { processed: true, derivedEventId, missingDerivedEvent: false }
    : { processed: false, derivedEventId: null, missingDerivedEvent: true };
}

// Semántica pura del efecto externo Resend. El SDK devuelve errores HTTP como
// valores (no siempre como excepciones) e incluye statusCode cuando lo conoce.
export interface ResendErrorLike {
  statusCode?: number | null;
  message?: string | null;
}

export interface ResendSendResponseLike {
  data?: { id?: string | null } | null;
  error?: ResendErrorLike | null;
}

export interface ResendSendOutcome {
  effectUncertain: boolean;
  providerMessageId: string | null;
  errorMessage: string | null;
}

export function isAmbiguousResendError(error: ResendErrorLike | null | undefined): boolean {
  const status = error?.statusCode;
  return !Number.isInteger(status) || status === 408 || status === 429 || (status as number) >= 500;
}

export function classifyResendSendResponse(response: ResendSendResponseLike): ResendSendOutcome {
  if (response.error) {
    return {
      effectUncertain: isAmbiguousResendError(response.error),
      providerMessageId: null,
      errorMessage: response.error.message ?? JSON.stringify(response.error),
    };
  }

  const providerMessageId = response.data?.id?.trim() || null;
  if (providerMessageId) {
    return { effectUncertain: false, providerMessageId, errorMessage: null };
  }

  return {
    effectUncertain: true,
    providerMessageId: null,
    errorMessage: 'Resend respondió sin ID de mensaje; efecto incierto',
  };
}

export const LATE_START_GRACE_MINUTES = 30;

export interface TaskReportStartState {
  start_time?: string | null;
  overall_status?: string | null;
}

/**
 * Un reporte cuenta como iniciado en cuanto registra la hora real de inicio o
 * entra en progreso/completado. No depende de tasks.status, que permanece
 * pending durante la ejecución de la limpieza.
 */
export function hasTaskReportStarted(reports: TaskReportStartState[] | null | undefined): boolean {
  return (reports ?? []).some((report) => {
    const hasStartTime = typeof report.start_time === 'string' && report.start_time.trim().length > 0;
    return hasStartTime || ['in_progress', 'completed', 'needs_review'].includes(report.overall_status ?? '');
  });
}

/** Resta minutos a una hora HH:MM sin envolver al día anterior. */
export function subtractMinutesFromTime(hhmm: string, minutes: number): string {
  const [hours, minutePart] = hhmm.split(':').map((value) => Number.parseInt(value, 10));
  const total = Math.max(0, hours * 60 + minutePart - minutes);
  const nextHours = Math.floor(total / 60).toString().padStart(2, '0');
  const nextMinutes = (total % 60).toString().padStart(2, '0');
  return `${nextHours}:${nextMinutes}`;
}

export function lateStartThreshold(nowMadrid: string): string {
  return subtractMinutesFromTime(nowMadrid, LATE_START_GRACE_MINUTES);
}

import { normalizePhoneE164 } from './phone.ts';

interface CleanerLike {
  name?: string | null;
  telefono?: string | null;
  whatsapp_phone_e164?: string | null;
  whatsapp_notifications_enabled?: boolean | null;
}

interface TaskLike {
  property?: string | null;
  date?: string | null;
  start_time?: string | null;
  startTime?: string | null;
}

interface EventPayloadLike {
  reason?: string | null;
  rejection_reason?: string | null;
}

export interface NotificationRecipient {
  recipient: string | null;
  enabled: boolean;
  kind: 'cleaner' | 'admin';
}

function clean(value: unknown): string {
  return String(value ?? '').trim();
}

function rejectionReason(payload: EventPayloadLike): string {
  return clean(payload.reason) || clean(payload.rejection_reason) || 'No disponible';
}

function escapeHtml(value: unknown): string {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

export function resolveNotificationRecipient(
  eventType: string,
  cleaner: CleanerLike,
  adminPhone: string | null | undefined,
): NotificationRecipient {
  if (eventType === 'task_rejected_alert') {
    const recipient = clean(adminPhone) || null;
    return { recipient, enabled: Boolean(recipient), kind: 'admin' };
  }

  const recipient = normalizePhoneE164(cleaner.telefono)
    || clean(cleaner.whatsapp_phone_e164)
    || null;
  return {
    recipient,
    enabled: Boolean(recipient),
    kind: 'cleaner',
  };
}

export function buildRejectedAlertBodyParameters(
  cleaner: CleanerLike,
  task: TaskLike,
  formattedDate: string,
): string[] {
  return [
    clean(cleaner.name) || 'Trabajadora sin nombre',
    clean(task.property) || 'Tarea sin propiedad',
    formattedDate,
    clean(task.start_time ?? task.startTime) || 'Sin hora',
  ];
}

export function shouldSendAdminEmailFallback(
  eventType: string,
  whatsappSucceeded: boolean,
  fallbackEmail: string | null | undefined,
): boolean {
  return eventType === 'task_rejected_alert'
    && !whatsappSucceeded
    && Boolean(clean(fallbackEmail));
}

export function buildRejectedAlertEmail(
  cleaner: CleanerLike,
  task: TaskLike,
  payload: EventPayloadLike,
  formattedDate: string,
): { subject: string; html: string } {
  const cleanerName = clean(cleaner.name) || 'Trabajadora sin nombre';
  const property = clean(task.property) || 'Tarea sin propiedad';
  const start = clean(task.start_time ?? task.startTime) || 'Sin hora';
  const reason = rejectionReason(payload);

  return {
    subject: `Tarea rechazada · ${cleanerName} · ${property}`,
    html: `
      <div style="font-family:Arial,sans-serif;max-width:640px;margin:0 auto;padding:20px;background:#f8fafc">
        <div style="background:#fff;border:1px solid #e5e7eb;border-radius:12px;padding:28px">
          <p style="margin:0 0 8px;color:#dc2626;font-size:12px;font-weight:700;text-transform:uppercase">Tarea rechazada</p>
          <h1 style="margin:0 0 18px;color:#111827;font-size:22px">Revisión operativa necesaria</h1>
          <table style="width:100%;border-collapse:collapse">
            <tr><td style="padding:7px 0;color:#6b7280">Trabajadora</td><td style="padding:7px 0;font-weight:600">${escapeHtml(cleanerName)}</td></tr>
            <tr><td style="padding:7px 0;color:#6b7280">Propiedad</td><td style="padding:7px 0">${escapeHtml(property)}</td></tr>
            <tr><td style="padding:7px 0;color:#6b7280">Fecha</td><td style="padding:7px 0">${escapeHtml(formattedDate)}</td></tr>
            <tr><td style="padding:7px 0;color:#6b7280">Hora</td><td style="padding:7px 0">${escapeHtml(start)}</td></tr>
            <tr><td style="padding:7px 0;color:#6b7280">Motivo</td><td style="padding:7px 0">${escapeHtml(reason)}</td></tr>
          </table>
          <p style="margin:22px 0 0;color:#6b7280;font-size:12px">WhatsApp administrativo no pudo entregar el aviso. Este correo es el canal de respaldo automático.</p>
        </div>
      </div>`,
  };
}

export interface WorkerScheduleInput {
  startTime?: string | null;
  endTime?: string | null;
  /** Duración total de la tarea, en minutos, cuando está disponible. */
  durationMinutes?: number | null;
}

export interface WorkerSchedule {
  startTime: string;
  endTime: string;
  durationMinutes: number;
}

const MINUTES_PER_DAY = 24 * 60;

const parseTime = (value?: string | null): number | null => {
  if (!value) return null;
  const [rawHours, rawMinutes = '0'] = value.slice(0, 5).split(':');
  const hours = Number(rawHours);
  const minutes = Number(rawMinutes);
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return null;
  if (hours < 0 || hours > 23 || minutes < 0 || minutes > 59) return null;
  return hours * 60 + minutes;
};

const formatTime = (minutes: number): string => {
  const normalized = ((minutes % MINUTES_PER_DAY) + MINUTES_PER_DAY) % MINUTES_PER_DAY;
  const hours = Math.floor(normalized / 60);
  const remainingMinutes = normalized % 60;
  return `${hours.toString().padStart(2, '0')}:${remainingMinutes.toString().padStart(2, '0')}`;
};

/**
 * Regla operativa común: todos empiezan a la misma hora y la duración total
 * se reparte entre el número real de trabajadores asignados.
 */
export function getTaskWorkerSchedule(
  task: WorkerScheduleInput,
  workerCount = 1,
): WorkerSchedule {
  const parsedStartMinutes = parseTime(task.startTime);
  const startMinutes = parsedStartMinutes ?? 0;
  const endMinutes = parseTime(task.endTime);
  const windowDuration = parsedStartMinutes === null || endMinutes === null
    ? 0
    : ((endMinutes - startMinutes) + MINUTES_PER_DAY) % MINUTES_PER_DAY || MINUTES_PER_DAY;
  const declaredDuration = Number(task.durationMinutes);
  // The explicit task schedule is authoritative. `durationMinutes` can still
  // contain a property's old estimate after a manager edits the task times.
  // Only use it when there is no usable schedule window.
  const totalDuration = windowDuration > 0
    ? windowDuration
    : Number.isFinite(declaredDuration) && declaredDuration > 0
      ? Math.round(declaredDuration)
      : 0;
  const normalizedWorkerCount = Number.isFinite(workerCount) && workerCount > 0
    ? Math.max(1, Math.ceil(workerCount))
    : 1;
  const durationMinutes = Math.max(0, Math.ceil(totalDuration / normalizedWorkerCount));

  return {
    startTime: formatTime(startMinutes),
    endTime: formatTime(startMinutes + durationMinutes),
    durationMinutes,
  };
}
